  paintHead(n);
  const nb = [];
  for (const e of gData.edges) {
    if (e.from === id && gData.byId[e.to]) nb.push({ node: gData.byId[e.to], rel: e.type, dir: '→' });
    else if (e.to === id && gData.byId[e.from]) nb.push({ node: gData.byId[e.from], rel: e.type, dir: '←' });
  }
