	u, _ = m.Update(cmd())
	m = u.(Model)
	if len(m.snap.Search) != 1 || m.tab != TabSearch {
		t.Errorf("in-flight result should apply; search=%d tab=%v", len(m.snap.Search), m.tab)
	}
