func TestConcurrentUninstallAndInstallDoNotInterleave(t *testing.T) {
	f := newSetupTestFixture(t)
	var inside atomic.Int32
	var overlaps atomic.Int32
	const racers = 8
	start := make(chan struct{})
	var wg sync.WaitGroup
	for i := 0; i < racers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			_ = withDaemonRegistrationLock(f.env, func() error {
				if inside.Add(1) != 1 {
					overlaps.Add(1)
				}
				defer inside.Add(-1)
				return nil
			})
		}()
	}
	close(start)
	wg.Wait()
	if overlaps.Load() != 0 {
		t.Fatalf("the machine-level daemon lock let %d callers in at once", overlaps.Load())
	}
}

