			if declared, ok := prop["maxLength"].(int); !ok || declared != mcpStringArgMaxBytes {
				t.Errorf("%s.%s declares maxLength %v, want %d", def["name"], name, prop["maxLength"], mcpStringArgMaxBytes)
			}
		}
